	@Test
	public void testBoundStatementPatternJoinPreservesValuesAndGraphMultiplicity() {
		CountingTripleSource tripleSource = new CountingTripleSource();
		QueryBindingSet row = boundStatement(tripleSource.statement);
		QueryBindingSet missing = new QueryBindingSet(row);
		missing.setBinding("o", vf.createLiteral("missing"));
		QueryBindingSet partial = new QueryBindingSet(row);
		partial.removeBinding("o");
		partial.addBinding("tag", vf.createLiteral("partial"));
		BindingSetAssignment left = new BindingSetAssignment();
		left.setBindingSets(List.of(row, row, row, missing, partial));

		Join join = new Join(left, new StatementPattern(Var.of("s"), Var.of("p"), Var.of("o")));
		QueryBindingSet completed = new QueryBindingSet(partial);
		completed.addBinding("o", tripleSource.statement.getObject());
		List<BindingSet> expected = new ArrayList<>(Collections.nCopies(6, row));
		expected.addAll(List.of(completed, completed));

		assertCountFreeRows(tripleSource, join, EmptyBindingSet.getInstance(), expected);
	}

	@Test
	public void testBoundLeftStatementPatternJoinPreservesGraphMultiplicity() {
		CountingTripleSource tripleSource = new CountingTripleSource();
		QueryBindingSet bindings = boundStatement(tripleSource.statement);

		BindingSetAssignment right = new BindingSetAssignment();
		List<BindingSet> rows = new ArrayList<>();
		List<BindingSet> expected = new ArrayList<>();
		for (int i = 0; i < 2; i++) {
			Value value = vf.createLiteral(i);
			QueryBindingSet row = new QueryBindingSet();
			row.addBinding("x", value);
			rows.add(row);
			QueryBindingSet joined = new QueryBindingSet(bindings);
			joined.addBinding("x", value);
			expected.addAll(List.of(joined, joined));
		}
		right.setBindingSets(rows);

		Join join = new Join(new StatementPattern(Var.of("s"), Var.of("p"), Var.of("o")), right);
		assertCountFreeRows(tripleSource, join, bindings, expected);
	}

