	@Test
	public void testFilteredValuesJoinMultipliesOnlyPassingRows() {
		CountingTripleSource tripleSource = new CountingTripleSource();
		BindingSetAssignment left = new BindingSetAssignment();
		QueryBindingSet row = boundStatement(tripleSource.statement);
		row.addBinding("p2", tripleSource.secondStatement.getPredicate());
		row.addBinding("o2", tripleSource.secondStatement.getObject());
		row.addBinding("tag", vf.createLiteral("keep"));
		QueryBindingSet rejected = new QueryBindingSet(row);
		rejected.setBinding("tag", vf.createLiteral("drop"));
		left.setBindingSets(List.of(row, rejected));

		Filter filteredLeft = new Filter(left,
				new Compare(Var.of("tag"), Var.of("drop", vf.createLiteral("drop")), Compare.CompareOp.NE));
		Join nested = new Join(
				new StatementPattern(Var.of("s"), Var.of("p"), Var.of("o")),
				new StatementPattern(Var.of("s"), Var.of("p2"), Var.of("o2")));
		assertCountFreeRows(tripleSource, new Join(filteredLeft, nested), EmptyBindingSet.getInstance(),
				Collections.nCopies(4, row));
	}

